#!/usr/bin/env python3
"""Human-reviewed survey additions, kept separate from literal catalogue rows."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parents[1]
D={'components':[],'anchors':[],'issues':[],'leads':[]}
def comp(key,name,source,page,**kw):
 D['components'].append(dict(key=key,name=name,source=source,page=str(page),**kw))
def group(prefix,source,page,parent,names,subsystem,**kw):
 for name in names.split('|'):
  key=prefix+'_'+name.lower().replace(' ','_').replace('-','_')
  comp(key,name,source,page,parent=parent,subsystem=subsystem,**kw)
def anchor(part,feature,source,page,raw,value=None,unit=None,**kw):
 D['anchors'].append(dict(part=part,feature=feature,source=source,page=str(page),raw=raw,value=value,unit=unit,**kw))
def issue(id,title,locator,details,resolution,status='open',marks=[],category='cross_source',severity='high',source=None):
 D['issues'].append(dict(id=id,title=title,locator=locator,details=details,resolution=resolution,status=status,marks=marks,category=category,severity=severity,source=source))
def lead(id,title,vendor,url,date,verification,priority,benefit,limitations,match):
 D['leads'].append(dict(id=id,title=title,vendor=vendor,url=url,date=date,verification=verification,priority=priority,benefit=benefit,limitations=limitations,match=match))

